with base as (
 select ms.id,ms.position,m.id material_id,m.title
 from public.material_sections ms join public.materials m on m.id=ms.material_id
 where m.id in (
 '28aa6204-d69c-4e06-8697-4856e2dbe4a5',
 'c3000000-0000-4000-8000-000000000011',
 'ffdfee3f-a282-498f-97c5-bd60f06ab767',
 '9a4eb5d1-cc50-4e12-913b-de4dc5cbdc82',
 '59b82f39-6cb6-4fb8-aca2-7bbc675255dd',
 '79981a61-376d-4665-98bb-6eeb5f7e1cda',
 '09ce815d-3f3c-46a4-bf12-ec83b367cb8d',
 '38b543e8-2f05-4682-b1c7-4de0df5b0762',
 '455d7bc0-d028-4026-af50-6f9943caab80')
 and coalesce(ms.content,'') not like '%[NUCLEO-FINAL-PEDAGOGIA-2026]%'
),
x as (
 select *,case
 when material_id='28aa6204-d69c-4e06-8697-4856e2dbe4a5' then
  case position when 1 then 'Aprofundamento específico: compreender a EJA exige reconhecer trajetórias escolares descontínuas, experiências de trabalho e conhecimentos construídos fora da escola.' when 2 then 'Aprofundamento específico: a condição de jovem, adulto ou idoso não define uma única forma de aprender; planejamento precisa partir de repertórios e necessidades concretas.' when 3 then 'Aprofundamento específico: currículo da EJA ganha sentido quando relaciona conhecimento escolar, experiências sociais e direito à continuidade dos estudos.' when 4 then 'Aprofundamento específico: práticas dialógicas permitem problematizar situações reais sem transformar a experiência do estudante em substituta do conhecimento sistematizado.' when 5 then 'Aprofundamento específico: avaliação deve acompanhar avanços e obstáculos sem reproduzir fracassos escolares anteriores como expectativa sobre o estudante.' when 6 then 'Aprofundamento específico: alfabetização e escolarização na EJA exigem respeito aos tempos de aprendizagem e objetivos intelectuais ambiciosos, sem infantilização.' when 7 then 'Aprofundamento específico: equidade envolve enfrentar barreiras de acesso, permanência e aprendizagem relacionadas a trabalho, território, gênero, raça e condições sociais.' when 8 then 'Aprofundamento específico: políticas e práticas precisam articular direito educacional, condições institucionais e reconhecimento dos sujeitos.' when 9 then 'Aprofundamento específico: uma análise crítica evita explicar evasão ou dificuldade apenas por características individuais e considera fatores escolares e sociais.' else 'Aprofundamento específico: domínio implica interpretar trajetórias, planejar respostas pedagógicas e justificar decisões com base em direitos, contexto e evidências.' end
 when material_id='c3000000-0000-4000-8000-000000000011' then
  case position when 1 then 'Aprofundamento específico: motivação não é apenas vontade; envolve metas, expectativas, valor atribuído à tarefa, percepção de competência e contexto de aprendizagem.' when 2 then 'Aprofundamento específico: autorregulação envolve planejar, monitorar e ajustar estratégias, e pode ser ensinada por meio de modelagem e reflexão sobre o próprio processo.' when 3 then 'Aprofundamento específico: atribuições sobre sucesso e fracasso influenciam persistência, mas precisam ser analisadas junto às condições reais da tarefa e do ensino.' when 4 then 'Aprofundamento específico: feedback útil informa progresso, aponta o próximo passo e preserva a possibilidade de revisão, em vez de apenas classificar o desempenho.' when 5 then 'Aprofundamento específico: estratégias de estudo precisam ser selecionadas de acordo com a tarefa; uma técnica útil para memorização pode ser insuficiente para resolver problemas complexos.' when 6 then 'Aprofundamento específico: dificuldades persistentes devem ser analisadas sem rotular o estudante, considerando conhecimento prévio, tarefa, ambiente e apoio pedagógico.' when 7 then 'Aprofundamento específico: autonomia não significa ausência de orientação; o apoio pode ser gradualmente retirado à medida que o estudante desenvolve controle sobre a aprendizagem.' when 8 then 'Aprofundamento específico: motivação e autorregulação articulam aspectos cognitivos, afetivos e sociais, evitando explicações que responsabilizem exclusivamente o aluno.' when 9 then 'Aprofundamento específico: uma leitura crítica diferencia evidência sobre comportamento de interpretações sobre intenção, interesse ou capacidade.' else 'Aprofundamento específico: domínio implica explicar mecanismos de autorregulação e transformá-los em decisões de ensino que ampliem participação, estratégia e autonomia.' end
 when material_id in ('ffdfee3f-a282-498f-97c5-bd60f06ab767','9a4eb5d1-cc50-4e12-913b-de4dc5cbdc82','59b82f39-6cb6-4fb8-aca2-7bbc675255dd') then
  case position when 1 then 'Aprofundamento específico: comece pela pergunta que o problema filosófico ou de pesquisa pretende tornar inteligível, distinguindo tema amplo de questão delimitada.' when 2 then 'Aprofundamento específico: conceitos filosóficos funcionam como ferramentas de análise; é preciso explicitar pressupostos antes de aplicar uma categoria a uma situação educacional.' when 3 then 'Aprofundamento específico: argumentos devem ser reconstruídos antes de avaliados, identificando premissas, conclusão e possíveis objeções.' when 4 then 'Aprofundamento específico: a relação teoria-prática aparece quando uma ideia orienta uma interpretação e a experiência permite testar seus limites ou consequências.' when 5 then 'Aprofundamento específico: diferentes concepções de educação implicam diferentes respostas sobre finalidade, conhecimento, autoridade, liberdade e formação humana.' when 6 then 'Aprofundamento específico: uma posição teórica ganha força quando reconhece problemas e limites, em vez de apresentar sua própria perspectiva como neutra.' when 7 then 'Aprofundamento específico: perguntas educacionais têm dimensão ética e política porque envolvem escolhas sobre valores, relações sociais e formas de vida.' when 8 then 'Aprofundamento específico: comparar perspectivas exige critério argumentativo; diferenças não são resolvidas apenas por preferência pessoal.' when 9 then 'Aprofundamento específico: pensamento crítico inclui reconhecer o que uma explicação consegue sustentar e aquilo que permanece em aberto.' else 'Aprofundamento específico: domínio filosófico significa formular problemas, analisar argumentos, comparar perspectivas e relacioná-las às finalidades da educação.' end
 when material_id='79981a61-376d-4665-98bb-6eeb5f7e1cda' then
  case position when 1 then 'Aprofundamento específico: ensinar História envolve construir noções de tempo, mudança, permanência, evidência e perspectiva, e não apenas memorizar acontecimentos.' when 2 then 'Aprofundamento específico: fontes históricas precisam ser interrogadas quanto à autoria, contexto, finalidade e limites, distinguindo vestígio de interpretação.' when 3 then 'Aprofundamento específico: diferentes grupos experimentam processos históricos de modos distintos; isso amplia a análise sem abandonar critérios de evidência.' when 4 then 'Aprofundamento específico: narrativas históricas escolares devem relacionar acontecimentos a processos, evitando listas descontextualizadas de datas e personagens.' when 5 then 'Aprofundamento específico: comparar fontes permite perceber divergências e construir interpretações justificadas, desenvolvendo pensamento histórico.' when 6 then 'Aprofundamento específico: questões históricas podem partir do cotidiano da criança, mas precisam avançar para conceitos e evidências que ultrapassem a experiência imediata.' when 7 then 'Aprofundamento específico: currículo deve enfrentar apagamentos e estereótipos, incorporando diferentes sujeitos históricos com contextualização e rigor.' when 8 then 'Aprofundamento específico: patrimônio, memória e história não são sinônimos; distingui-los ajuda a analisar como sociedades selecionam e preservam narrativas sobre o passado.' when 9 then 'Aprofundamento específico: ensinar História exige cuidado com anacronismos e julgamentos atuais aplicados mecanicamente a contextos históricos diferentes.' else 'Aprofundamento específico: domínio implica analisar fontes, construir relações temporais e explicar processos históricos com evidências e perspectivas contextualizadas.' end
 when material_id='09ce815d-3f3c-46a4-bf12-ec83b367cb8d' then
  case position when 1 then 'Aprofundamento específico: avaliação externa produz informações em escala, mas seu significado depende de matriz, população, instrumento, escala e finalidade.' when 2 then 'Aprofundamento específico: proficiência, desempenho e aprendizagem não são termos intercambiáveis; cada medida representa uma construção específica.' when 3 then 'Aprofundamento específico: indicadores permitem comparar padrões, mas não explicam sozinhos as causas de diferenças entre estudantes, escolas ou redes.' when 4 then 'Aprofundamento específico: resultados precisam ser lidos junto a contexto socioeconômico, condições de oferta, currículo e práticas escolares.' when 5 then 'Aprofundamento específico: usar avaliação externa para melhorar ensino exige transformar resultado agregado em hipóteses sobre necessidades e ações possíveis.' when 6 then 'Aprofundamento específico: responsabilização pode gerar efeitos indesejados quando indicadores são usados isoladamente para premiar, punir ou ranquear.' when 7 then 'Aprofundamento específico: equidade exige observar distribuição dos resultados e desigualdades de oportunidade, não apenas médias globais.' when 8 then 'Aprofundamento específico: avaliações externas podem dialogar com avaliação interna, mas as duas respondem a perguntas diferentes e não devem ser confundidas.' when 9 then 'Aprofundamento específico: interpretação responsável explicita incertezas, limitações do instrumento e o que o indicador não permite concluir.' else 'Aprofundamento específico: domínio implica ler indicadores tecnicamente e pedagogicamente, articulando escala, contexto, finalidade e limites da evidência.' end
 when material_id='38b543e8-2f05-4682-b1c7-4de0df5b0762' then
  case position when 1 then 'Aprofundamento específico: avaliação da aprendizagem deve ser ligada às finalidades do ensino e ao tipo de evidência que se pretende produzir.' when 2 then 'Aprofundamento específico: avaliação diagnóstica, formativa e somativa podem cumprir funções distintas; a diferença está principalmente no uso pedagógico da informação.' when 3 then 'Aprofundamento específico: critérios tornam o julgamento mais transparente e ajudam a alinhar atividade, objetivo e evidência.' when 4 then 'Aprofundamento específico: instrumentos variados ampliam evidências, mas nenhum instrumento é adequado para todos os objetivos.' when 5 then 'Aprofundamento específico: feedback precisa apoiar ação posterior; informar o erro sem orientar revisão tem valor limitado.' when 6 then 'Aprofundamento específico: notas sintetizam julgamentos, mas não substituem registros e interpretações necessárias para acompanhar processos.' when 7 then 'Aprofundamento específico: avaliação equitativa considera barreiras de participação sem transformar diferença de desempenho em diagnóstico individual automático.' when 8 then 'Aprofundamento específico: avaliação, planejamento e ensino formam um ciclo; evidência deve alimentar decisões posteriores.' when 9 then 'Aprofundamento específico: uma prática avaliativa madura reconhece erros de medida, critérios inadequados e efeitos indesejados sobre aprendizagem.' else 'Aprofundamento específico: domínio implica escolher instrumentos coerentes, interpretar evidências e usar resultados para promover aprendizagem.' end
 when material_id='455d7bc0-d028-4026-af50-6f9943caab80' then
  case position when 1 then 'Aprofundamento específico: acompanhamento não é apenas registro; é interpretação contínua de evidências para decidir se objetivos, estratégias e condições precisam ser modificados.' when 2 then 'Aprofundamento específico: replanejar não significa abandonar o objetivo, mas revisar caminhos quando as evidências mostram que a estratégia não está produzindo o efeito esperado.' when 3 then 'Aprofundamento específico: decisões devem considerar conhecimento prévio, barreiras, ritmo, recursos e oportunidades oferecidas.' when 4 then 'Aprofundamento específico: registros comparáveis ao longo do tempo ajudam a perceber evolução sem reduzir o estudante a um número isolado.' when 5 then 'Aprofundamento específico: intervenções precisam ser suficientemente específicas para permitir observar se produziram mudança.' when 6 then 'Aprofundamento específico: o professor deve distinguir dificuldade de conteúdo, dificuldade de tarefa e barreira de acesso antes de decidir como intervir.' when 7 then 'Aprofundamento específico: acompanhamento equitativo combina altas expectativas com apoios proporcionais às barreiras identificadas.' when 8 then 'Aprofundamento específico: replanejamento integra avaliação, didática, currículo e gestão do tempo, tornando o ensino responsivo às evidências.' when 9 then 'Aprofundamento específico: uma decisão pode precisar ser revista mesmo quando parece intuitivamente adequada; evidência contrária é parte da aprendizagem profissional.' else 'Aprofundamento específico: domínio implica observar, interpretar, decidir, intervir e verificar novamente, mantendo o planejamento como hipótese revisável.' end
 end || ' [NUCLEO-FINAL-PEDAGOGIA-2026]' extra from base)
update public.material_sections ms
set content=trim(ms.content)||E'\n\n'||x.extra,updated_at=now()
from x where ms.id=x.id;
